5: .attachmentList {
6:   appearance: none;
7:   -moz-user-focus: normal;
8:   margin: 0;
9:   padding: 3px;
10:   background-color: var(--layout-background-2);
11:   color: var(--layout-color-2);
12:   border: none;
13:   display: flex;
14:   overflow-x: hidden;
15:   align-items: start;
16:   align-content: start;
17:   flex: 1;
18:   flex-direction: row;
19:   flex-wrap: wrap;
20: 
21:   &[collapsed] {
22:     display: none;
23:     block-size: 0;
24:   }
25: 
26:   :root[lwt-tree] & {
27:     background-color: var(--sidebar-background);
28:     color: var(--sidebar-color);
29:   }
30: }
31: 
32: .attachmentItem {
33:   position: relative;
34:   border: 1px solid transparent;
35:   min-inline-size: 10em;
36:   padding: 1px 3px;
37:   border-radius: 2px;
38:   display: flex;
39:   align-items: baseline;
40:   flex-shrink: 1;
41: 
42:   &:hover {
43:     background-color: color-mix(in srgb, currentColor 15%, transparent);
44:     border-color: transparent;
45:   }
46: 
47:   &[selected] {
48:     border-color: color-mix(in srgb, currentColor 20%, transparent);
49:     background-color: color-mix(in srgb, currentColor 20%, transparent);
50:     color: inherit;
51:   }
52: 
53:   & > * {
54:     /* We treat the entire attachment item as a single object for click events.
55:      * This ensures that dragging will drag the entire widget by default, and
56:      * click event targets will point to the attachmentItem, rather than a
57:      * descendant. */
58:     pointer-events: none;
59:   }
60: 
61:   & > .attachmentcell-icon {
62:     flex: 0 0 auto;
63:     align-self: center;
64:     -moz-context-properties: fill;
65:     fill: var(--selected-item-color);
66:   }
67: 
68:   & > .attachmentcell-name {
69:     flex: 0 1 auto;
70:     white-space: nowrap;
71:     overflow-x: hidden;
72:     text-overflow: ellipsis;
73:   }
74: 
75:   & > .attachmentcell-extension {
76:     /* The extension part grows to fill the available space after the attachment
77:      * name, but the name part shrinks when we do not have enough space. */
78:     flex: 1 0 auto;
79:   }
80: 
81:   & > .attachmentcell-size {
82:     flex: 0 0 auto;
83:   }
84: 
85:   &:not(.notfound):hover .text-link {
86:     text-decoration: underline;
87:   }
88: 
89:   .attachmentList:focus &[selected] {
90:     background-color: var(--selected-item-color);
91:     color: var(--selected-item-text-color);
92: 
93:     & .attachmentcell-size {
94:       opacity: 0.8;
95:     }
96: 
97:     & > * {
98:       color: inherit;
99:     }
100:   }
101: 
102:   .attachmentList[seltype="multiple"]:focus &[current="true"] {
103:     outline: 1px solid;
104: 
105:     &[selected] {
106:       border-color: var(--sidebar-highlight-border-color, var(--item-focus-selected-border-color));
107:     }
108:   }
109: 
110:   /* Hide the drop indicator for the message pane attachment list. */
